package javax.microedition.rms;
import androidport.AndroidBridge; import java.io.*; import java.util.*;
public class RecordStore {private final File f;private final Vector rec=new Vector();private RecordStore(String n)throws Exception{f=new File(AndroidBridge.appFiles(),"rms_"+n+".dat");load();}public static RecordStore openRecordStore(String n,boolean c)throws Exception{RecordStore r=new RecordStore(n);if(c&&!r.f.exists()){r.f.createNewFile();}return r;}private void load(){try{DataInputStream d=new DataInputStream(new FileInputStream(f));while(d.available()>0){int n=d.readInt();byte[] b=new byte[n];d.readFully(b);rec.addElement(b);}d.close();}catch(Throwable ignored){}}
 private void save()throws Exception{DataOutputStream d=new DataOutputStream(new FileOutputStream(f));for(int i=0;i<rec.size();i++){byte[] b=(byte[])rec.elementAt(i);d.writeInt(b.length);d.write(b);}d.close();}
 public int getNumRecords(){return rec.size();} public byte[] getRecord(int id)throws Exception{return (byte[])rec.elementAt(id-1);} public int addRecord(byte[] b,int o,int n)throws Exception{byte[] x=new byte[n];System.arraycopy(b,o,x,0,n);rec.addElement(x);save();return rec.size();} public void setRecord(int id,byte[] b,int o,int n)throws Exception{byte[] x=new byte[n];System.arraycopy(b,o,x,0,n);rec.setElementAt(x,id-1);save();} public void closeRecordStore()throws Exception{save();}
}
